const fs=require('fs'),path=require('path'),os=require('os');const AdmZip=require('adm-zip');const{execFileSync}=require('child_process');const{path7za}=require('7zip-bin');const{createExtractorFromData}=require('node-unrar-js');
const JOBS=[
 {name:'Haywrite',orig:30959,origFile:165168,tr:42397,trFile:160765,fix:['Wizard_Wizard_fall_1','Wizard_fall_1'],onlyRu:true},
 {name:'Abigail',orig:18657,origFile:135279,tr:18728,trFile:107659,onlyRu:true},
 {name:'Haley',orig:17674,origFile:135277,tr:18092,trFile:97534,onlyRu:true},
 {name:'Shane',orig:24068,origFile:135281,tr:24647,trFile:101640,onlyRu:true},
 {name:'Metalcore',orig:29995,origFile:153355,tr:40982,trFile:153753,onlyRu:false}
];
function h(){return{APIKEY:process.env.NEXUS_API_KEY,'User-Agent':'nexus-loader-pkg50bundle/1.0'}}
async function nj(u){const r=await fetch(u,{headers:h()}),j=await r.json().catch(()=>null);if(!r.ok)throw Error('Nexus '+r.status+' '+u);return j}
async function dl(id,f){const a=await nj(`https://api.nexusmods.com/v1/games/stardewvalley/mods/${id}/files/${f}/download_link.json`),m=(a||[]).find(x=>x&&(x.URI||x.uri));if(!m)throw Error('no mirror '+id);const r=await fetch(m.URI||m.uri,{redirect:'follow'});if(!r.ok)throw Error('mirror '+r.status+' '+id);return Buffer.from(await r.arrayBuffer())}
async function ex(b){const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'p50b-')),arc=path.join(tmp,'a.bin'),out=path.join(tmp,'out');fs.mkdirSync(out);fs.writeFileSync(arc,b);try{execFileSync(path7za,['x',arc,`-o${out}`,'-y'],{stdio:'pipe',timeout:30000})}catch{const magic=b.subarray(0,8).toString('hex');if(!magic.startsWith('52617221'))throw Error('extract failed '+magic);const wb=fs.readFileSync(require.resolve('node-unrar-js/esm/js/unrar.wasm')),wasmBinary=wb.buffer.slice(wb.byteOffset,wb.byteOffset+wb.byteLength),x=await createExtractorFromData({data:Uint8Array.from(b).buffer,wasmBinary}),g=x.extract();for(const it of g.files){const hh=it.fileHeader||{},n=String(hh.name||'').replace(/\\/g,'/').replace(/^\/+/,''),d=path.resolve(out,n);if(!n||!d.startsWith(path.resolve(out)+path.sep))continue;if(hh.flags&&hh.flags.directory){fs.mkdirSync(d,{recursive:true});continue}if(!it.extraction)continue;fs.mkdirSync(path.dirname(d),{recursive:true});fs.writeFileSync(d,Buffer.from(it.extraction))}}const rows=[];function w(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);e.isDirectory()?w(p):rows.push({p:path.relative(out,p).split(path.sep).join('/'),f:p,s:fs.statSync(p).size})}}w(out);return{tmp,rows}}
function strip(s){let o='',q=0,e=0;for(let i=0;i<s.length;i++){let c=s[i],n=s[i+1];if(q){o+=c;if(e)e=0;else if(c==='\\')e=1;else if(c==='"')q=0;continue}if(c==='"'){q=1;o+=c;continue}if(c==='/'&&n==='/'){while(i<s.length&&s[i]!=='\n')i++;o+='\n';continue}if(c==='/'&&n==='*'){i+=2;while(i<s.length-1&&!(s[i]==='*'&&s[i+1]==='/'))i++;i++;continue}o+=c}return o.replace(/,\s*([}\]])/g,'$1')}
function parseFile(f){return JSON.parse(strip(fs.readFileSync(f,'utf8').replace(/^\uFEFF/,'')))}
function dict(rows,re){const out={};for(const r of rows.filter(x=>re.test('/'+x.p))){const o=parseFile(r.f);for(const [k,v] of Object.entries(o))out[k]=v}return out}
module.exports=async(req,res)=>{const z=new AdmZip(),report=[];const temps=[];try{for(const j of JOBS){const [ob,tb]=await Promise.all([dl(j.orig,j.origFile),dl(j.tr,j.trFile)]),ox=await ex(ob),tx=await ex(tb);temps.push(ox.tmp,tx.tmp);const def=dict(ox.rows,/\/i18n\/default\.json$/i),ruRows=tx.rows.filter(r=>/\/i18n\/ru\.json$/i.test('/'+r.p));if(!ruRows.length)throw Error(j.name+' ru.json missing');let merged={};for(const r of ruRows){let o=parseFile(r.f);if(j.fix&&Object.prototype.hasOwnProperty.call(o,j.fix[0])){o[j.fix[1]]=o[j.fix[0]];delete o[j.fix[0]];}for(const[k,v]of Object.entries(o))merged[k]=v;const outPath='Mods/'+r.p;z.addFile(outPath,Buffer.from(JSON.stringify(o,null,2)+'\n','utf8'));}
const dk=Object.keys(def),rk=Object.keys(merged),missing=dk.filter(k=>!(k in merged)),extra=rk.filter(k=>!(k in def));if(missing.length||extra.length)throw Error(`${j.name} parity missing=${missing.length} extra=${extra.length}`);
let other=0;if(!j.onlyRu){for(const r of tx.rows){if(/\/i18n\/ru\.json$/i.test('/'+r.p)||/manifest\.json$|readme/i.test(r.p))continue;z.addFile('Mods/'+r.p,fs.readFileSync(r.f));other++;}}
report.push({name:j.name,originalModId:j.orig,translationModId:j.tr,defaultKeys:dk.length,ruKeys:rk.length,missing:0,extra:0,otherFiles:other});}
const reportText=['PACKAGE 50 VERIFIED RU BUNDLE','',...report.map(x=>`${x.name}: ${x.defaultKeys}/${x.ruKeys} keys, missing=0 extra=0, translation=${x.translationModId}, otherFiles=${x.otherFiles}`)].join('\n')+'\n';z.addFile('PACKAGE_50_TRANSLATION_REPORT.txt',Buffer.from(reportText,'utf8'));const buf=z.toBuffer();if(String(req.query.status||'')==='1')return res.json({ok:true,mods:report.length,files:z.getEntries().filter(e=>!e.isDirectory).length,zipBytes:buf.length,report});res.setHeader('Content-Type','application/zip');res.setHeader('Content-Disposition','attachment; filename="PACKAGE_50_VERIFIED_RU_5.zip"');res.setHeader('Cache-Control','no-store');return res.status(200).send(buf);}catch(e){return res.status(500).json({ok:false,error:String(e.message||e)})}finally{for(const t of temps)try{fs.rmSync(t,{recursive:true,force:true})}catch{}}};
